"use client"
import { useEffect, useState, useCallback } from "react"
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from "recharts"
import { TrendingUp, Calendar, Activity, AlertCircle } from 'lucide-react'

interface AppPyResponse {
  mytime: string
  readings: Record<string, number>
  sensor_keys: string[]
  history: Record<string, Record<string, any>>
  prediction: Record<string, { trend: string; "10": number | null; "30": number | null }>
  error?: string
}

const SENSOR_COLORS: Record<string, string> = {
  Temperature: "#ff6b35",
  Humidity: "#004e89",
  "Cahaya (LDR)": "#f7b801",
  "Soil Moisture": "#1b4332",
}

const SENSOR_RANGES: Record<string, { min: number; max: number; unit: string }> = {
  Temperature: { min: 18, max: 30, unit: "°C" },
  Humidity: { min: 30, max: 80, unit: "%" },
  "Cahaya (LDR)": { min: 100, max: 800, unit: "lux" },
  "Soil Moisture": { min: 30, max: 80, unit: "%" },
}

export default function TrendsPage() {
  const [currentData, setCurrentData] = useState<AppPyResponse | null>(null)
  const [historyData, setHistoryData] = useState<any[]>([])
  const [forecastData, setForecastData] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  const calculateForecast = useCallback((data: any[], sensor: string) => {
    if (data.length < 3) return null

    const values = data.map((d) => d[sensor]).filter((v) => v !== undefined && v !== null) as number[]
    if (values.length < 3) return null

    const n = values.length
    const sum = values.reduce((a, b) => a + b, 0)
    const avg = sum / n
    const variance = values.reduce((a, v) => a + Math.pow(v - avg, 2), 0) / n
    const stdDev = Math.sqrt(variance)

    // Simple linear regression for trend
    const xValues = Array.from({ length: n }, (_, i) => i)
    const xySum = xValues.reduce((sum, x, i) => sum + x * values[i], 0)
    const xxSum = xValues.reduce((sum, x) => sum + x * x, 0)
    const xSum = xValues.reduce((a, b) => a + b, 0)

    const slope = (n * xySum - xSum * sum) / (n * xxSum - xSum * xSum)
    const intercept = (sum - slope * xSum) / n

    // Forecast 5 and 15 minutes ahead
    const forecast5Min = intercept + slope * (n)
    const forecast15Min = intercept + slope * (n + 2)

    return {
      current: values[n - 1],
      forecast5Min: Math.max(0, forecast5Min),
      forecast15Min: Math.max(0, forecast15Min),
      trend: slope > 0.5 ? "up" : slope < -0.5 ? "down" : "stable",
      stdDev: stdDev.toFixed(2),
      avg: avg.toFixed(2),
    }
  }, [])

  const fetchSensorData = useCallback(async () => {
    try {
      const response = await fetch("/api/sensors", {
        cache: "no-store",
      })

      if (!response.ok) throw new Error("Failed to fetch")
      const result: AppPyResponse = await response.json()

      setCurrentData(result)

      if (result.history && typeof result.history === "object") {
        const historyArray = Object.entries(result.history)
          .map(([, item]: [string, any]) => ({
            ...item,
            timestamp: new Date(item.timestamp || Date.now()).toLocaleTimeString("id-ID", {
              hour: "2-digit",
              minute: "2-digit",
            }),
          }))
          .slice(-50)
        setHistoryData(historyArray)

        const sensors = result.sensor_keys || []
        const forecastArray: any[] = []
        
        // Current data
        forecastArray.push({
          time: "Now",
          ...Object.fromEntries(sensors.map((s) => [s, historyArray[historyArray.length - 1]?.[s]])),
        })

        // 5 minutes forecast
        forecastArray.push({
          time: "+5 Min",
          ...Object.fromEntries(sensors.map((s) => {
            const forecast = calculateForecast(historyArray, s)
            return [s, forecast?.forecast5Min]
          })),
        })

        // 15 minutes forecast
        forecastArray.push({
          time: "+15 Min",
          ...Object.fromEntries(sensors.map((s) => {
            const forecast = calculateForecast(historyArray, s)
            return [s, forecast?.forecast15Min]
          })),
        })

        setForecastData(forecastArray)
      }
    } catch (error) {
      console.error("Error fetching data:", error)
    } finally {
      setLoading(false)
    }
  }, [calculateForecast])

  useEffect(() => {
    fetchSensorData()
    const interval = setInterval(fetchSensorData, 5000)
    return () => clearInterval(interval)
  }, [fetchSensorData])

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-emerald-200 border-t-emerald-600 rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-slate-700 font-semibold">Loading trends analysis...</p>
        </div>
      </div>
    )
  }

  const sensors = currentData?.sensor_keys || []

  return (
    <div className="space-y-8">
      {/* Header */}
      <div>
        <h1 className="text-4xl font-bold text-slate-900">Trends Analysis</h1>
        <p className="text-slate-600 mt-1">Statistical analysis and real-time forecasting of sensor data</p>
      </div>

      {/* Statistical Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {sensors.map((sensor) => {
          const values = historyData.map((d) => d[sensor]).filter((v) => v !== undefined && v !== null) as number[]
          
          if (values.length === 0) return null

          const avg = values.reduce((a, b) => a + b, 0) / values.length
          const min = Math.min(...values)
          const max = Math.max(...values)
          const variance = values.reduce((a, v) => a + Math.pow(v - avg, 2), 0) / values.length
          const stdDev = Math.sqrt(variance)
          const current = values[values.length - 1]
          const previous = values[values.length - 2] || current
          const change = ((current - previous) / previous) * 100

          const range = SENSOR_RANGES[sensor]

          return (
            <div key={sensor} className="bg-white rounded-xl shadow-md border border-emerald-200 p-4">
              <div className="flex items-start justify-between mb-3">
                <div>
                  <p className="text-slate-600 text-sm font-medium">{sensor}</p>
                  <p className="text-2xl font-bold text-slate-900 mt-1">
                    {current.toFixed(1)}<span className="text-sm font-normal text-slate-500 ml-1">{range.unit}</span>
                  </p>
                </div>
                {change > 0 ? (
                  <TrendingUp className="w-5 h-5 text-red-600" />
                ) : (
                  <TrendingUp className="w-5 h-5 text-blue-600" />
                )}
              </div>
              <div className="space-y-2 text-xs border-t border-slate-100 pt-3 mt-3">
                <div className="flex justify-between">
                  <span className="text-slate-600">Range:</span>
                  <span className="font-semibold text-slate-900">{range.min} - {range.max}{range.unit}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-600">σ (Std Dev):</span>
                  <span className="font-semibold text-slate-900">{stdDev.toFixed(2)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-600">Δ (Change):</span>
                  <span className={`font-semibold ${change > 0 ? 'text-red-600' : 'text-blue-600'}`}>
                    {change > 0 ? '+' : ''}{change.toFixed(1)}%
                  </span>
                </div>
              </div>
            </div>
          )
        })}
      </div>

      {/* Detailed Trends - Line Chart with Multiple Sensors */}
      {historyData.length > 0 && (
        <div className="bg-white rounded-xl shadow-md border border-slate-200 p-6">
          <div className="flex items-center gap-3 mb-6">
            <Activity className="w-5 h-5 text-emerald-600" />
            <div>
              <h2 className="text-lg font-bold text-slate-900">Detailed Trends Over Time</h2>
              <p className="text-xs text-slate-500 mt-1">Real-time historical data showing each sensor's movement pattern</p>
            </div>
          </div>
          <ResponsiveContainer width="100%" height={400}>
            <LineChart data={historyData} margin={{ top: 5, right: 30, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="timestamp" stroke="#64748b" style={{ fontSize: "12px" }} />
              <YAxis stroke="#64748b" style={{ fontSize: "12px" }} yAxisId="left" />
              <YAxis stroke="#64748b" style={{ fontSize: "12px" }} yAxisId="right" orientation="right" />
              <Tooltip
                contentStyle={{
                  backgroundColor: "#f1f5f9",
                  border: "1px solid #cbd5e1",
                  borderRadius: "8px",
                }}
              />
              <Legend />
              {sensors.map((sensor, idx) => (
                <Line
                  key={sensor}
                  type="monotone"
                  dataKey={sensor}
                  stroke={SENSOR_COLORS[sensor]}
                  strokeWidth={2}
                  dot={false}
                  yAxisId={idx % 2 === 0 ? "left" : "right"}
                  isAnimationActive={false}
                />
              ))}
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* Forecast Trends - Line Chart (Not Bar Chart) for Next 15 Minutes */}
      {forecastData.length > 0 && (
        <div className="bg-white rounded-xl shadow-md border border-slate-200 p-6">
          <div className="flex items-center gap-3 mb-6">
            <TrendingUp className="w-5 h-5 text-purple-600" />
            <div>
              <h2 className="text-lg font-bold text-slate-900">Forecast Trends (Next 15 Minutes)</h2>
              <p className="text-xs text-slate-500 mt-1">ML-based linear regression prediction of sensor trajectory</p>
            </div>
          </div>
          <ResponsiveContainer width="100%" height={350}>
            <LineChart data={forecastData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="time" stroke="#64748b" style={{ fontSize: "12px" }} />
              <YAxis stroke="#64748b" style={{ fontSize: "12px" }} />
              <Tooltip
                contentStyle={{
                  backgroundColor: "#f1f5f9",
                  border: "1px solid #cbd5e1",
                  borderRadius: "8px",
                }}
              />
              <Legend />
              {sensors.map((sensor) => (
                <Line
                  key={sensor}
                  type="monotone"
                  dataKey={sensor}
                  stroke={SENSOR_COLORS[sensor]}
                  strokeWidth={3}
                  dot={{ fill: SENSOR_COLORS[sensor], r: 6 }}
                  isAnimationActive={false}
                />
              ))}
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* Data Quality Metrics */}
      <div className="bg-emerald-50 rounded-xl border border-emerald-200 p-6">
        <h3 className="text-lg font-bold text-slate-900 mb-4">Data Quality Metrics</h3>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div>
            <p className="text-slate-600 text-sm font-medium">Data Points</p>
            <p className="text-2xl font-bold text-slate-900 mt-1">{historyData.length}</p>
          </div>
          <div>
            <p className="text-slate-600 text-sm font-medium">Time Range</p>
            <p className="text-2xl font-bold text-slate-900 mt-1">{historyData.length > 1 ? `${historyData.length * 5}s` : "N/A"}</p>
          </div>
          <div>
            <p className="text-slate-600 text-sm font-medium">Update Rate</p>
            <p className="text-2xl font-bold text-slate-900 mt-1">5s</p>
          </div>
          <div>
            <p className="text-slate-600 text-sm font-medium">Status</p>
            <p className="text-2xl font-bold text-emerald-600 mt-1">Active</p>
          </div>
        </div>
      </div>
    </div>
  )
}
